#!/usr/bin/env bats
# test_scripts.bats - BATS test suite for defensive bash scripts
# Tests common_utils.sh and safe_backup.sh functionality

# Setup runs before each test
setup() {
    # Get script directory
    SCRIPT_DIR="$(cd "$(dirname "$BATS_TEST_FILENAME")" && pwd)"

    # Source the common utilities
    source "${SCRIPT_DIR}/common_utils.sh"

    # Create temporary test directory
    TEST_DIR="$(mktemp -d -t bats_test.XXXXXXXXXX)"

    # Disable color output for testing
    RED=""
    YELLOW=""
    GREEN=""
    BLUE=""
    NC=""
}

# Teardown runs after each test
teardown() {
    # Clean up test directory
    if [[ -d "${TEST_DIR}" ]]; then
        rm -rf "${TEST_DIR}"
    fi
}

# Test common_utils.sh functions

@test "validate_directory accepts valid directory" {
    mkdir -p "${TEST_DIR}/valid_dir"
    run validate_directory "${TEST_DIR}/valid_dir"
    [ "$status" -eq 0 ]
}

@test "validate_directory rejects non-existent path" {
    run validate_directory "${TEST_DIR}/nonexistent"
    [ "$status" -eq 1 ]
}

@test "validate_directory rejects file as directory" {
    touch "${TEST_DIR}/file.txt"
    run validate_directory "${TEST_DIR}/file.txt"
    [ "$status" -eq 1 ]
}

@test "validate_directory rejects empty path" {
    run validate_directory ""
    [ "$status" -eq 1 ]
}

@test "validate_file accepts valid file" {
    touch "${TEST_DIR}/valid_file.txt"
    run validate_file "${TEST_DIR}/valid_file.txt"
    [ "$status" -eq 0 ]
}

@test "validate_file rejects non-existent file" {
    run validate_file "${TEST_DIR}/nonexistent.txt"
    [ "$status" -eq 1 ]
}

@test "validate_file rejects directory as file" {
    mkdir -p "${TEST_DIR}/dir"
    run validate_file "${TEST_DIR}/dir"
    [ "$status" -eq 1 ]
}

@test "command_exists finds existing command" {
    run command_exists "bash"
    [ "$status" -eq 0 ]
}

@test "command_exists fails for non-existent command" {
    run command_exists "nonexistent_command_xyz"
    [ "$status" -eq 1 ]
}

@test "create_temp_dir creates directory" {
    TMPDIR=$(create_temp_dir "test")
    [ -d "${TMPDIR}" ]
    rm -rf "${TMPDIR}"
}

@test "safe_remove_dir removes existing directory" {
    mkdir -p "${TEST_DIR}/to_remove"
    run safe_remove_dir "${TEST_DIR}/to_remove"
    [ "$status" -eq 0 ]
    [ ! -d "${TEST_DIR}/to_remove" ]
}

@test "safe_remove_dir refuses to remove critical paths" {
    run safe_remove_dir "/"
    [ "$status" -eq 1 ]

    run safe_remove_dir "/home"
    [ "$status" -eq 1 ]
}

@test "get_timestamp returns ISO 8601 format" {
    timestamp=$(get_timestamp)
    # Check format: YYYY-MM-DDTHH:MM:SSZ
    [[ "${timestamp}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$ ]]
}

@test "get_timestamp_filename returns safe format" {
    timestamp=$(get_timestamp_filename)
    # Check format: YYYYMMDD_HHMMSS
    [[ "${timestamp}" =~ ^[0-9]{8}_[0-9]{6}$ ]]
}

# Test safe_backup.sh functionality

@test "safe_backup.sh exists and is executable" {
    [ -x "${SCRIPT_DIR}/safe_backup.sh" ]
}

@test "safe_backup.sh shows usage with -h" {
    run bash "${SCRIPT_DIR}/safe_backup.sh" -h
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "Usage:" ]]
}

@test "safe_backup.sh fails without source directory" {
    run bash "${SCRIPT_DIR}/safe_backup.sh"
    [ "$status" -eq 1 ]
}

@test "safe_backup.sh creates backup of directory" {
    # Create source directory with test file
    mkdir -p "${TEST_DIR}/source"
    echo "test content" > "${TEST_DIR}/source/file.txt"

    # Create backup directory
    mkdir -p "${TEST_DIR}/backup"

    # Run backup script
    run bash "${SCRIPT_DIR}/safe_backup.sh" "${TEST_DIR}/source" "${TEST_DIR}/backup"
    [ "$status" -eq 0 ]

    # Check that backup file was created
    backup_files=("${TEST_DIR}/backup"/*.tar.gz)
    [ -f "${backup_files[0]}" ]
}

@test "safe_backup.sh validates source exists" {
    run bash "${SCRIPT_DIR}/safe_backup.sh" "${TEST_DIR}/nonexistent" "${TEST_DIR}/backup"
    [ "$status" -eq 1 ]
    [[ "${output}" =~ "not a directory" ]]
}

@test "safe_backup.sh creates backup directory if missing" {
    # Create source directory
    mkdir -p "${TEST_DIR}/source"
    echo "test" > "${TEST_DIR}/source/file.txt"

    # Run backup without creating backup dir first
    run bash "${SCRIPT_DIR}/safe_backup.sh" "${TEST_DIR}/source" "${TEST_DIR}/new_backup"
    [ "$status" -eq 0 ]

    # Verify backup directory was created
    [ -d "${TEST_DIR}/new_backup" ]
}

@test "safe_backup.sh handles custom backup name" {
    # Create source
    mkdir -p "${TEST_DIR}/source"
    echo "test" > "${TEST_DIR}/source/file.txt"
    mkdir -p "${TEST_DIR}/backup"

    # Run with custom name
    run bash "${SCRIPT_DIR}/safe_backup.sh" -n "custom" "${TEST_DIR}/source" "${TEST_DIR}/backup"
    [ "$status" -eq 0 ]

    # Check custom name in backup file
    backup_files=("${TEST_DIR}/backup"/custom_*.tar.gz)
    [ -f "${backup_files[0]}" ]
}

@test "safe_backup.sh verifies backup integrity" {
    # Create source
    mkdir -p "${TEST_DIR}/source"
    echo "test" > "${TEST_DIR}/source/file.txt"
    mkdir -p "${TEST_DIR}/backup"

    # Run backup
    run bash "${SCRIPT_DIR}/safe_backup.sh" "${TEST_DIR}/source" "${TEST_DIR}/backup"
    [ "$status" -eq 0 ]
    [[ "${output}" =~ "verification passed" ]]
}

